changeSet.sql:
ALTER TABLE reaction
ADD CONSTRAINT chk_reaction_usefulness CHECK (usefulness IN ('HELPFUL', 'UNHELPFUL'));
ALTER TABLE reaction
ADD CONSTRAINT chk_reaction_response_present CHECK (usefulness IS NOT NULL OR action IS NOT NULL);

rollback.sql:
DELETE FROM reaction WHERE action IS NULL;
ALTER TABLE reaction DROP CONSTRAINT IF EXISTS chk_reaction_response_present;
ALTER TABLE reaction DROP CONSTRAINT IF EXISTS chk_reaction_usefulness;

DELETE FROM reaction WHERE usefulness IS NULL AND action IS NULL;
ALTER TABLE reaction
ADD CONSTRAINT chk_reaction_response_present CHECK (usefulness IS NOT NULL OR action IS NOT NULL);
